package org.apache.commons.math.distribution;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.exception.MathIllegalArgumentException;
import org.apache.commons.math.exception.MathRuntimeException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.special.Gamma;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for PoissonDistributionImpl#cumulativeProbability
 */
public class PoissonDistributionImpl_cumulativeProbability_TriageGen2Test {

    private static final double DELTA = 1e-10;

    @Test
    public void testCumulativeProbability_NegativeX() {
        // Test branch: if (x < 0) return 0
        PoissonDistributionImpl dist = new PoissonDistributionImpl(5.0);
        assertEquals(0.0, dist.cumulativeProbability(-1), DELTA);
        assertEquals(0.0, dist.cumulativeProbability(-100), DELTA);
    }

    @Test
    public void testCumulativeProbability_MaxIntX() {
        // Test branch: if (x == Integer.MAX_VALUE) return 1
        PoissonDistributionImpl dist = new PoissonDistributionImpl(5.0);
        assertEquals(1.0, dist.cumulativeProbability(Integer.MAX_VALUE), DELTA);
    }

    @Test
    public void testCumulativeProbability_NormalRange() {
        // Test standard calculation path
        double mean = 3.0;
        PoissonDistributionImpl dist = new PoissonDistributionImpl(mean);

        // For Poisson, CDF(x) = P(X <= x)
        // For x=0, P(X=0) = e^-mean * mean^0 / 0! = e^-3
        double expectedZero = Math.exp(-mean);
        assertEquals(expectedZero, dist.cumulativeProbability(0), DELTA);

        // For x=1, P(X <= 1) = P(0) + P(1) = e^-3 + e^-3 * 3 = 4 * e^-3
        double expectedOne = expectedZero + (expectedZero * mean);
        assertEquals(expectedOne, dist.cumulativeProbability(1), DELTA);
    }

    @Test
    public void testCumulativeProbability_WithCustomEpsilonAndMaxIterations() {
        // Test path using the constructor with epsilon and maxIterations
        double mean = 10.0;
        double epsilon = 1e-12;
        int maxIterations = 100;
        PoissonDistributionImpl dist = new PoissonDistributionImpl(mean, epsilon, maxIterations);

        // Just ensure it executes without exception and returns a valid probability
        double result = dist.cumulativeProbability(10);
        assert(result >= 0.0 && result <= 1.0);
    }

    @Test
    public void testCumulativeProbability_LargeX() {
        // Test behavior for large x that is not MAX_VALUE
        PoissonDistributionImpl dist = new PoissonDistributionImpl(2.0);
        // As x increases, CDF should approach 1.0
        double result = dist.cumulativeProbability(100);
        assertEquals(1.0, result, 1e-7);
    }

    @Test(expected = MathIllegalArgumentException.class)
    public void testConstructor_InvalidMean() {
        // Poisson mean must be positive. 
        // This tests if the distribution setup affects the cumulativeProbability call indirectly via Gamma
        new PoissonDistributionImpl(-1.0);
    }
}
